            await roleManager.CreateAsync(new IdentityRole(role));
    }

    if (!db.Shipments.Any())
    {
        db.Shipments.AddRange(
            new Shipment { TrackingNumber = "SWF-001-2024", Origin = "New York, NY", Destination = "Los Angeles, CA", Status = ShipmentStatus.InTransit, CreatedAt = DateTime.UtcNow.AddDays(-3), EstimatedDelivery = DateTime.UtcNow.AddDays(2), Notes = "Fragile items" },
            new Shipment { TrackingNumber = "SWF-002-2024", Origin = "Chicago, IL", Destination = "Houston, TX", Status = ShipmentStatus.Pending, CreatedAt = DateTime.UtcNow.AddDays(-1), EstimatedDelivery = DateTime.UtcNow.AddDays(4) },
            new Shipment { TrackingNumber = "SWF-003-2024", Origin = "Seattle, WA", Destination = "Miami, FL", Status = ShipmentStatus.PickedUp, CreatedAt = DateTime.UtcNow.AddDays(-2), EstimatedDelivery = DateTime.UtcNow.AddDays(5), Notes = "Priority shipping" },
