@page "/shipments"
@attribute [Authorize(Roles = "Dispatcher")]
@attribute [StreamRendering]
@inject HttpClient Http

<PageTitle>Dispatcher Dashboard</PageTitle>

<h2 class="mb-4">📋 Dispatcher Dashboard</h2>

@if (shipments == null)
{
    <p><em>Loading shipments...</em></p>
}
else
{
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Filter by tracking number or destination..."
               @bind="searchFilter" @bind:event="oninput" />
    </div>

    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var shipment in FilteredShipments)
                {
                    <tr>
                        <td><strong>@shipment.TrackingNumber</strong></td>
                        <td>@shipment.Origin</td>
                        <td>@shipment.Destination</td>
                        <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                        <td>@shipment.EstimatedDelivery?.ToString("MMM dd, yyyy")</td>
                        <td>
                            <div class="d-flex gap-2">
                                <select class="form-select form-select-sm" style="width: auto;"
                                        @bind="shipment.Status">
                                    <option value="Pending">Pending</option>
                                    <option value="PickedUp">Picked Up</option>
                                    <option value="InTransit">In Transit</option>
                                    <option value="OutForDelivery">Out For Delivery</option>
                                    <option value="Delivered">Delivered</option>
                                    <option value="Exception">Exception</option>
                                </select>
                                <button class="btn btn-sm btn-primary" @onclick="() => UpdateShipment(shipment)">
                                    Save
                                </button>
                            </div>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>

    @if (statusMessage != null)
    {
        <div class="alert alert-success alert-dismissible mt-3">
            @statusMessage
            <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
        </div>
    }
}

@code {
    private List<ShipmentDto>? shipments;
    private string searchFilter = string.Empty;
    private string? statusMessage;

    private IEnumerable<ShipmentDto> FilteredShipments =>
        shipments?.Where(s =>
            s.TrackingNumber.Contains(searchFilter, StringComparison.OrdinalIgnoreCase) ||
            s.Destination.Contains(searchFilter, StringComparison.OrdinalIgnoreCase)) ?? [];

    protected override async Task OnInitializedAsync()
    {
        shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("api/shipments");
    }

    private async Task UpdateShipment(ShipmentDto shipment)
    {
        var response = await Http.PutAsJsonAsync($"api/shipments/{shipment.Id}", shipment);
        if (response.IsSuccessStatusCode)
        {
            statusMessage = $"Shipment {shipment.TrackingNumber} updated successfully.";
        }
    }

    private string GetStatusBadgeClass(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "PickedUp" => "bg-info",
        "InTransit" => "bg-primary",
        "OutForDelivery" => "bg-warning text-dark",
        "Delivered" => "bg-success",
        "Exception" => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/track"
@attribute [Authorize]
@attribute [StreamRendering]
@inject HttpClient Http

<PageTitle>Track Shipment</PageTitle>

<h2 class="mb-4">📦 Track Your Shipment</h2>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g., SWF-001-2024)"
                   @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="TrackShipmentAsync" disabled="@isLoading">
                @if (isLoading)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Track
            </button>
        </div>
    </div>
</div>

@if (errorMessage != null)
{
    <div class="alert alert-danger">@errorMessage</div>
}

@if (shipment != null)
{
    <div class="card shadow-sm">
        <div class="card-header bg-primary text-white">
            <h5 class="mb-0">Shipment: @shipment.TrackingNumber</h5>
        </div>
        <div class="card-body">
            <div class="row mb-4">
                <div class="col-md-3">
                    <strong>Origin:</strong><br />@shipment.Origin
                </div>
                <div class="col-md-3">
                    <strong>Destination:</strong><br />@shipment.Destination
                </div>
                <div class="col-md-3">
                    <strong>Status:</strong><br />
                    <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@FormatStatus(shipment.Status)</span>
                </div>
                <div class="col-md-3">
                    <strong>Est. Delivery:</strong><br />
                    @(shipment.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "TBD")
                </div>
            </div>

            @if (!string.IsNullOrEmpty(shipment.Notes))
            {
                <div class="alert alert-info">
                    <strong>Notes:</strong> @shipment.Notes
                </div>
            }

            <!-- Status Timeline -->
            <h6 class="mt-4 mb-3">Shipment Progress</h6>
            <div class="d-flex justify-content-between position-relative px-3 mb-3">
                <div class="position-absolute top-50 start-0 end-0" style="height: 4px; background: #dee2e6; z-index: 0; margin-top: -2px;"></div>
                <div class="position-absolute top-50 start-0" style="height: 4px; background: #0d6efd; z-index: 1; margin-top: -2px; width: @GetProgressWidth(shipment.Status);"></div>

                @foreach (var step in statusSteps)
                {
                    <div class="text-center position-relative" style="z-index: 2;">
                        <div class="rounded-circle d-flex align-items-center justify-content-center mx-auto mb-1 @(IsStepCompleted(shipment.Status, step.Key) ? "bg-primary text-white" : "bg-light border")"
                             style="width: 36px; height: 36px;">
                            @if (IsStepCompleted(shipment.Status, step.Key))
                            {
                                <span>✓</span>
                            }
                        </div>
                        <small class="d-block" style="font-size: 0.7rem;">@step.Value</small>
                    </div>
                }
            </div>
        </div>
    </div>
}

@code {
    private string trackingNumber = string.Empty;
    private ShipmentDto? shipment;
    private string? errorMessage;
    private bool isLoading;

    private readonly List<KeyValuePair<string, string>> statusSteps =
    [
        new("Pending", "Pending"),
        new("PickedUp", "Picked Up"),
        new("InTransit", "In Transit"),
        new("OutForDelivery", "Out for Delivery"),
        new("Delivered", "Delivered")
    ];

    private async Task HandleKeyDown(Microsoft.AspNetCore.Components.Web.KeyboardEventArgs e)
    {
        if (e.Key == "Enter") await TrackShipmentAsync();
    }

    private async Task TrackShipmentAsync()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        isLoading = true;
        errorMessage = null;
        shipment = null;

        try
        {
            var response = await Http.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber.Trim())}");
            if (response.IsSuccessStatusCode)
            {
                shipment = await response.Content.ReadFromJsonAsync<ShipmentDto>();
            }
            else
            {
                errorMessage = "Shipment not found. Please check the tracking number and try again.";
            }
        }
        catch
        {
            errorMessage = "An error occurred while tracking the shipment. Please try again.";
        }
        finally
        {
            isLoading = false;
        }
    }

    private bool IsStepCompleted(string currentStatus, string step)
    {
        var order = new[] { "Pending", "PickedUp", "InTransit", "OutForDelivery", "Delivered" };
        var currentIndex = Array.IndexOf(order, currentStatus);
        var stepIndex = Array.IndexOf(order, step);
        return currentIndex >= 0 && stepIndex >= 0 && stepIndex <= currentIndex;
    }

    private string GetProgressWidth(string status) => status switch
    {
        "Pending" => "0%",
        "PickedUp" => "25%",
        "InTransit" => "50%",
        "OutForDelivery" => "75%",
        "Delivered" => "100%",
        _ => "0%"
    };

    private string FormatStatus(string status) => status switch
    {
        "PickedUp" => "Picked Up",
        "InTransit" => "In Transit",
        "OutForDelivery" => "Out for Delivery",
        _ => status
    };

    private string GetStatusBadgeClass(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "PickedUp" => "bg-info",
        "InTransit" => "bg-primary",
        "OutForDelivery" => "bg-warning text-dark",
        "Delivered" => "bg-success",
        "Exception" => "bg-danger",
        _ => "bg-secondary"
    };
}

