 @code {
     private string trackingNumber = string.Empty;
     private ShipmentDto? shipment;
     private string? errorMessage;
     private bool isLoading;

     private readonly List<KeyValuePair<string, string>> statusSteps =
     [
         new("Pending", "Pending"),
         new("PickedUp", "Picked Up"),
         new("InTransit", "In Transit"),
         new("OutForDelivery", "Out for Delivery"),
         new("Delivered", "Delivered")
     ];

     private async Task HandleKeyDown(Microsoft.AspNetCore.Components.Web.KeyboardEventArgs e)
     {
         if (e.Key == "Enter") await TrackShipmentAsync();
     }

     private async Task TrackShipmentAsync()
     {
         if (string.IsNullOrWhiteSpace(trackingNumber)) return;

         isLoading = true;
         errorMessage = null;
         shipment = null;

         try
         {
             var response = await Http.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber.Trim())}");
             if (response.IsSuccessStatusCode)
             {
                 shipment = await response.Content.ReadFromJsonAsync<ShipmentDto>();
             }
             else
             {
                 errorMessage = "Shipment not found. Please check the tracking number and try again.";
             }
         }
         catch
         {
             errorMessage = "An error occurred while tracking the shipment. Please try again.";
         }
         finally
         {
             isLoading = false;
         }
     }

     private bool IsStepCompleted(string currentStatus, string step)
     {
         var order = new[] { "Pending", "PickedUp", "InTransit", "OutForDelivery", "Delivered" };
         var currentIndex = Array.IndexOf(order, currentStatus);
         var stepIndex = Array.IndexOf(order, step);
         return currentIndex >= 0 && stepIndex >= 0 && stepIndex <= currentIndex;
     }

     private string GetProgressWidth(string status) => status switch
     {
         "Pending" => "0%",
         "PickedUp" => "25%",
         "InTransit" => "50%",
         "OutForDelivery" => "75%",
         "Delivered" => "100%",
         _ => "0%"
     };

     private string FormatStatus(string status) => status switch
     {
         "PickedUp" => "Picked Up",
         "InTransit" => "In Transit",
         "OutForDelivery" => "Out for Delivery",
         _ => status
     };

     private string GetStatusBadgeClass(string status) => status switch
     {
         "Pending" => "bg-secondary",
         "PickedUp" => "bg-info",
         "InTransit" => "bg-primary",
         "OutForDelivery" => "bg-warning text-dark",
         "Delivered" => "bg-success",
         "Exception" => "bg-danger",
         _ => "bg-secondary"
     };
 }
